/* Miss-rate simulator for an (S, E, B) LRU cache — the tool that settles the
 * "write h or m in every cell" exam question.  gcc -O2 csim.c -o csim */
#include <stdio.h>
#include <string.h>

#define MAX_SETS 1024
#define MAX_WAYS 16

static int S, E, B, s_bits, b_bits;      /* S sets, E ways, B-byte blocks */
static long tag[MAX_SETS][MAX_WAYS];     /* -1 marks an invalid line      */
static long age[MAX_SETS][MAX_WAYS], clk;
static long hits, misses, evictions;

static int log2i(int n) { int k = 0; while (n > 1) { n >>= 1; k++; } return k; }

static void cache_init(int sets, int ways, int block) {
    S = sets; E = ways; B = block;
    s_bits = log2i(S); b_bits = log2i(B);
    memset(tag, -1, sizeof tag);
    clk = hits = misses = evictions = 0;
}

/* 1 on hit, 0 on miss. Pure LRU: the least recently used line is the victim. */
static int access(long addr) {
    long block = addr >> b_bits;
    int set = (int) (block & (S - 1));
    long t = block >> s_bits;
    int lru = 0;

    clk++;
    for (int i = 0; i < E; i++)
        if (tag[set][i] == t) { age[set][i] = clk; hits++; return 1; }

    misses++;
    for (int i = 0; i < E; i++) {
        if (tag[set][i] == -1) { lru = i; goto fill; }
        if (age[set][i] < age[set][lru]) lru = i;
    }
    evictions++;
fill:
    tag[set][lru] = t;
    age[set][lru] = clk;
    return 0;
}

int main(void) {
    /* CENG331 final: char matrix[5][5] at address 0, summed column-wise, on a
     * direct-mapped cache with 4 sets and 2-byte blocks. */
    char grid[5][5];
    cache_init(4, 1, 2);
    for (int col = 0; col < 5; col++)
        for (int row = 0; row < 5; row++)
            grid[row][col] = access(5 * row + col) ? 'h' : 'm';

    for (int row = 0; row < 5; row++)
        printf("%c %c %c %c %c\n", grid[row][0], grid[row][1], grid[row][2],
               grid[row][3], grid[row][4]);
    printf("hits %ld  misses %ld  evictions %ld  miss rate %.0f%%\n",
           hits, misses, evictions, 100.0 * misses / (hits + misses));
    return 0;
}
